DROP TABLE IF EXISTS `inventories`;
CREATE TABLE `inventories`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '库存ID',
  `sku_id` bigint UNSIGNED NOT NULL COMMENT 'SKU ID',
  `stock_quantity` int NOT NULL DEFAULT 0 COMMENT '实际库存数量',
  `locked_quantity` int NOT NULL DEFAULT 0 COMMENT '锁定库存数量',
  `warning_quantity` int NOT NULL DEFAULT 10 COMMENT '库存预警数量',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sku_id`(`sku_id` ASC) USING BTREE,
  CONSTRAINT `fk_inventories_sku` FOREIGN KEY (`sku_id`) REFERENCES `product_skus` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 3008 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '商品库存表' ROW_FORMAT = Dynamic;

